using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    // The default resolver knows how to produce metadata for any type at
    // runtime (reflection-based).  Without it (e.g. in a trimmed /
    // source-gen-only app) TryGetTypeInfo would return false.
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ── 1. Strongly-typed metadata retrieval ────────────────────────────
//    GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no casting.
JsonTypeInfo<Person> personMeta = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Type handled : {personMeta.Type.Name}");
Console.WriteLine($"Properties   : {string.Join(", ", personMeta.Properties.Select(p => p.Name))}");
Console.WriteLine();

// ── 2. Probe without throwing ───────────────────────────────────────
//    TryGetTypeInfo returns false instead of throwing when metadata
//    isn't available (e.g. the resolver doesn't cover the type).
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    // Safe to downcast — we know the concrete generic type.
    var typed = (JsonTypeInfo<Person>)info!;
    Console.WriteLine($"[Probe] Metadata for Person found — {typed.Properties.Count} properties");
}

// Use an empty resolver so that nothing is resolvable.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // resolves nothing
};

if (!limited.TryGetTypeInfo(typeof(Person), out _))
{
    Console.WriteLine("[Probe] Metadata for Person NOT available (no exception thrown)");
}

// ── supporting type ─────────────────────────────────────────────────
public record Person(string Name, int Age);

